import { BrowserRouter, Routes, Route } from 'react-router-dom';

// 1. Import all your Context Providers
import { AuthProvider } from './context/AuthContext';
import { SearchProvider } from './context/SearchContext'; 
import { CartProvider } from './context/CartContext';     

import { ProtectedRoute } from './features/auth/ProtectedRoute';
import { DashboardLayout } from './layouts/DashboardLayout';
import { CartDrawer } from './features/orders/CartDrawer'; 

import { Marketplace } from './pages/Marketplace';
import { Login } from './pages/Login';
import { Register } from './pages/Register';
import { Orders } from './pages/Orders';
import { Reports } from './pages/Report';

export default function App() {
  console.log({
    AuthProvider,
    CartProvider,
    SearchProvider,
    DashboardLayout,
    Marketplace,
    CartDrawer
  });
  return (
    <AuthProvider>
      {/* 2. Wrap the app in the Cart and Search Providers */}
      <CartProvider>
        <SearchProvider>
          <BrowserRouter>
            <Routes>
              {/* Public Routes */}
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />

              {/* Protected Routes */}
              <Route path="/" element={
                <ProtectedRoute><DashboardLayout><Marketplace /></DashboardLayout></ProtectedRoute>
              } />
              <Route path="/marketplace" element={
                <ProtectedRoute><DashboardLayout><Marketplace /></DashboardLayout></ProtectedRoute>
              } />
              <Route path="/orders" element={
                <ProtectedRoute><DashboardLayout><Orders /></DashboardLayout></ProtectedRoute>
              } />
              <Route path="/reports" element={
                <ProtectedRoute allowedRoles={['admin']}><DashboardLayout><Reports /></DashboardLayout></ProtectedRoute>
              } />
            </Routes>

            {/* 3. Mount Cart Drawer globally so it opens on top of any page */}
            <CartDrawer />

          </BrowserRouter>
        </SearchProvider>
      </CartProvider>
    </AuthProvider>
  );
}
